import{_ as e,o as i,c as o,a2 as t}from"./chunks/framework.D3fmyz3M.js";const u=JSON.parse('{"title":"FAQ","description":"微前端落地过程中的高频疑问，按主题分组速查。","frontmatter":{"title":"FAQ","description":"微前端落地过程中的高频疑问，按主题分组速查。"},"headers":[],"relativePath":"appendix/faq.md","filePath":"appendix/faq.md","lastUpdated":1792674288000}'),n={name:"appendix/faq.md"};function r(l,a,s,d,h,c){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>按提出问题的场景分组。每条都给出结论和对应章节，不展开长篇论证。</p><h2 id="选型" tabindex="-1">选型 <a class="header-anchor" href="#选型" aria-label="Permalink to &quot;选型&quot;">​</a></h2><h3 id="微前端和组件库、monorepo-有什么区别" tabindex="-1">微前端和组件库、Monorepo 有什么区别？ <a class="header-anchor" href="#微前端和组件库、monorepo-有什么区别" aria-label="Permalink to &quot;微前端和组件库、Monorepo 有什么区别？&quot;">​</a></h3><ul><li><strong>组件库</strong>解决&quot;代码复用&quot;，运行时仍在同一个应用里。</li><li><strong>Monorepo</strong> 解决&quot;代码仓库管理&quot;，构建产物仍可能一起发布。</li><li><strong>微前端</strong>解决&quot;独立开发、独立部署、运行时组装&quot;，是组织与交付问题，不是代码组织问题。</li></ul><p>如果只是想把公共组件抽出来，用组件库或 Monorepo 就够了。参见<a href="/micro-frontend-docs/guide/what-is">微前端是什么</a>。</p><h3 id="团队只有-5-个人-需要微前端吗" tabindex="-1">团队只有 5 个人，需要微前端吗？ <a class="header-anchor" href="#团队只有-5-个人-需要微前端吗" aria-label="Permalink to &quot;团队只有 5 个人，需要微前端吗？&quot;">​</a></h3><p>多数情况下不需要。人数少时沟通成本低，拆分反而增加集成、联调、部署的复杂度。先把模块边界做清楚，等出现&quot;发布互相阻塞&quot;再考虑。</p><h3 id="新项目应该选哪个方案" tabindex="-1">新项目应该选哪个方案？ <a class="header-anchor" href="#新项目应该选哪个方案" aria-label="Permalink to &quot;新项目应该选哪个方案？&quot;">​</a></h3><p>新项目优先考虑构建时集成（Module Federation）或组件级方案（Web Components）。只有需要强隔离的遗留系统共存时，才选 iframe / qiankun / wujie 这类运行时方案。参见<a href="/micro-frontend-docs/guide/decision-tree">选型决策树</a>。</p><h3 id="qiankun-和-micro-app、wujie-该怎么选" tabindex="-1">qiankun 和 micro-app、wujie 该怎么选？ <a class="header-anchor" href="#qiankun-和-micro-app、wujie-该怎么选" aria-label="Permalink to &quot;qiankun 和 micro-app、wujie 该怎么选？&quot;">​</a></h3><ul><li><strong>qiankun</strong>：生态最成熟，HTML Entry + 沙箱，适合中后台聚合；对 Vite、Vue 3 的现代构建需要额外处理。</li><li><strong>micro-app</strong>：接入方式是自定义标签，改动小，支持 Vite / esmodule 子应用，适合想低成本接入的团队。</li><li><strong>wujie</strong>：iframe 执行 JS + Shadow DOM 渲染，隔离与性能折中，适合需要强隔离又要保留 DOM 能力的场景。</li></ul><p>三者都能解决 80% 的常见需求，差异主要在隔离强度、接入成本、生态与调试体验。</p><h2 id="接入与运行" tabindex="-1">接入与运行 <a class="header-anchor" href="#接入与运行" aria-label="Permalink to &quot;接入与运行&quot;">​</a></h2><h3 id="子应用一定要支持跨域吗" tabindex="-1">子应用一定要支持跨域吗？ <a class="header-anchor" href="#子应用一定要支持跨域吗" aria-label="Permalink to &quot;子应用一定要支持跨域吗？&quot;">​</a></h3><p>运行时方案（qiankun、micro-app、wujie）通常需要主应用 <code>fetch</code> 子应用的 HTML 或资源，因此子应用静态服务必须返回 CORS 头。本地开发时 Vite 配置 <code>server.cors: true</code> 即可。</p><h3 id="子应用用-vite-能接入-qiankun-吗" tabindex="-1">子应用用 Vite 能接入 qiankun 吗？ <a class="header-anchor" href="#子应用用-vite-能接入-qiankun-吗" aria-label="Permalink to &quot;子应用用 Vite 能接入 qiankun 吗？&quot;">​</a></h3><p>可以，但要额外处理：</p><ol><li>子应用打包成 UMD / 库模式，产出固定的入口 JS 与 CSS。</li><li>关闭代码分割，或使用 <code>inlineDynamicImports</code>。</li><li>入口 HTML 由子应用自己维护，引用固定产物名。</li></ol><p>本项目示例就是把 Vite 子应用构建后以 <code>preview</code> 方式提供，供 qiankun 加载。</p><h3 id="子应用一定要导出生命周期吗" tabindex="-1">子应用一定要导出生命周期吗？ <a class="header-anchor" href="#子应用一定要导出生命周期吗" aria-label="Permalink to &quot;子应用一定要导出生命周期吗？&quot;">​</a></h3><ul><li><strong>single-spa / qiankun</strong>：是，必须导出 <code>bootstrap</code>、<code>mount</code>、<code>unmount</code>。</li><li><strong>micro-app / wujie</strong>：多数情况下不需要改造成生命周期，按普通应用启动即可。</li><li><strong>Module Federation</strong>：不需要，暴露的是模块，由宿主按需 <code>import</code>。</li></ul><h3 id="本地开发时子应用能独立启动吗" tabindex="-1">本地开发时子应用能独立启动吗？ <a class="header-anchor" href="#本地开发时子应用能独立启动吗" aria-label="Permalink to &quot;本地开发时子应用能独立启动吗？&quot;">​</a></h3><p>能，而且应该能。示例中每个子应用都通过环境变量判断是否处于微前端环境：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> isMicro</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((window </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> any</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).__POWERED_BY_QIANKUN__);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isMicro) {</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 独立挂载，方便单人开发与调试</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>独立可运行是微前端拆分的前提，否则子应用团队会被主应用阻塞。</p><h2 id="样式与沙箱" tabindex="-1">样式与沙箱 <a class="header-anchor" href="#样式与沙箱" aria-label="Permalink to &quot;样式与沙箱&quot;">​</a></h2><h3 id="shadow-dom-能解决所有样式冲突吗" tabindex="-1">Shadow DOM 能解决所有样式冲突吗？ <a class="header-anchor" href="#shadow-dom-能解决所有样式冲突吗" aria-label="Permalink to &quot;Shadow DOM 能解决所有样式冲突吗？&quot;">​</a></h3><p>不能。Shadow DOM 隔离的是选择器作用域，但以下情况仍会穿透或失效：</p><ul><li>全局 CSS 变量与继承属性仍会影响内部。</li><li><code>document.body</code> 上的全局样式（如字体、背景）仍然作用。</li><li>第三方组件往 <code>document.head</code> 注入样式时不受 Shadow DOM 约束。</li></ul><h3 id="qiankun-的-experimentalstyleisolation-够用吗" tabindex="-1">qiankun 的 <code>experimentalStyleIsolation</code> 够用吗？ <a class="header-anchor" href="#qiankun-的-experimentalstyleisolation-够用吗" aria-label="Permalink to &quot;qiankun 的 `experimentalStyleIsolation` 够用吗？&quot;">​</a></h3><p>它会给子应用样式加前缀选择器，能解决大部分&quot;互相污染&quot;，但对 <code>!important</code>、<code>body</code>、<code>html</code> 级规则效果有限。强隔离需求建议直接用 wujie 或 iframe。</p><h3 id="js-沙箱能完全隔离吗" tabindex="-1">JS 沙箱能完全隔离吗？ <a class="header-anchor" href="#js-沙箱能完全隔离吗" aria-label="Permalink to &quot;JS 沙箱能完全隔离吗？&quot;">​</a></h3><p>不能。常见的 <code>Proxy</code> 沙箱拦截的是全局变量读写，仍存在逃逸路径（如闭包持有原生 <code>window</code>、<code>document</code> 引用）。沙箱的目标是&quot;降低冲突概率&quot;，不是安全边界。真正的安全隔离只有 iframe（跨域时）。</p><h2 id="路由与通信" tabindex="-1">路由与通信 <a class="header-anchor" href="#路由与通信" aria-label="Permalink to &quot;路由与通信&quot;">​</a></h2><h3 id="主应用和子应用的路由谁来管" tabindex="-1">主应用和子应用的路由谁来管？ <a class="header-anchor" href="#主应用和子应用的路由谁来管" aria-label="Permalink to &quot;主应用和子应用的路由谁来管？&quot;">​</a></h3><p>两种模式：</p><ul><li><strong>主应用管路由</strong>：主应用根据 URL 决定激活哪个子应用（single-spa、qiankun、micro-app 的默认方式）。</li><li><strong>子应用自治</strong>：子应用内部有自己的路由，主应用只负责挂载容器（wujie、Module Federation 常见）。</li></ul><p>混用时最容易出现&quot;双路由打架&quot;，建议明确一层为唯一事实来源。</p><h3 id="刷新页面后子应用-404-怎么办" tabindex="-1">刷新页面后子应用 404 怎么办？ <a class="header-anchor" href="#刷新页面后子应用-404-怎么办" aria-label="Permalink to &quot;刷新页面后子应用 404 怎么办？&quot;">​</a></h3><p>子应用的静态服务需要配置 history fallback，把所有未知路径回退到 <code>index.html</code>。Vite 的 <code>preview</code> 默认已支持；Nginx 需要 <code>try_files $uri $uri/ /index.html;</code>。</p><h3 id="通信一定要用全局状态吗" tabindex="-1">通信一定要用全局状态吗？ <a class="header-anchor" href="#通信一定要用全局状态吗" aria-label="Permalink to &quot;通信一定要用全局状态吗？&quot;">​</a></h3><p>不一定。按耦合度从低到高：</p><ol><li><code>CustomEvent</code> / <code>postMessage</code>（事件总线，最松）</li><li>属性 / props 传值（父子明确）</li><li>全局状态（qiankun <code>initGlobalState</code>、micro-app <code>setData</code>、wujie <code>bus</code>）</li></ol><p>优先用事件和 props，只有确实需要共享状态时才引入全局 store。参见<a href="/micro-frontend-docs/principles/communication">通信机制</a>。</p><h2 id="构建与部署" tabindex="-1">构建与部署 <a class="header-anchor" href="#构建与部署" aria-label="Permalink to &quot;构建与部署&quot;">​</a></h2><h3 id="子应用独立部署后-主应用怎么知道新版本" tabindex="-1">子应用独立部署后，主应用怎么知道新版本？ <a class="header-anchor" href="#子应用独立部署后-主应用怎么知道新版本" aria-label="Permalink to &quot;子应用独立部署后，主应用怎么知道新版本？&quot;">​</a></h3><p>两种做法：</p><ul><li><strong>主应用存子应用清单</strong>：发布子应用时更新清单（JSON），主应用启动时拉取，可实现灰度与回滚。</li><li><strong>固定 URL + 缓存控制</strong>：子应用入口文件名带 hash 或查询参数，主应用不做版本感知。</li></ul><p>生产环境建议第一种，配合 CDN 刷新。参见<a href="/micro-frontend-docs/advanced/deployment">独立部署与灰度</a>。</p><h3 id="module-federation-的-shared-为什么必须单例" tabindex="-1">Module Federation 的 <code>shared</code> 为什么必须单例？ <a class="header-anchor" href="#module-federation-的-shared-为什么必须单例" aria-label="Permalink to &quot;Module Federation 的 `shared` 为什么必须单例？&quot;">​</a></h3><p>Vue、React 这类框架在运行时依赖模块级单例状态。如果宿主与远程各自加载一份，会出现响应式系统、调度器、Context 不互通的问题。配置 <code>shared: { vue: { singleton: true } }</code> 让双方共用同一份实例。</p><h3 id="为什么本地启动-mf-要先构建远程应用" tabindex="-1">为什么本地启动 MF 要先构建远程应用？ <a class="header-anchor" href="#为什么本地启动-mf-要先构建远程应用" aria-label="Permalink to &quot;为什么本地启动 MF 要先构建远程应用？&quot;">​</a></h3><p>远程应用需要产出 <code>remoteEntry.js</code> 才能被宿主消费。Vite 插件在 dev 模式下对远程支持有限，因此本项目的脚本先构建远程、用 <code>preview</code> 提供服务，再启动宿主开发服务器。参见<a href="/micro-frontend-docs/schemes/module-federation">Module Federation</a>。</p><h3 id="github-pages-部署后资源-404" tabindex="-1">GitHub Pages 部署后资源 404？ <a class="header-anchor" href="#github-pages-部署后资源-404" aria-label="Permalink to &quot;GitHub Pages 部署后资源 404？&quot;">​</a></h3><p>多数是 <code>base</code> 配置不对。项目站点地址是 <code>https://&lt;user&gt;.github.io/&lt;repo&gt;/</code>，因此构建时必须设置 <code>base = &quot;/&lt;repo&gt;/&quot;</code>。本项目通过 CI 注入 <code>DEPLOY_BASE</code>，本地开发保持 <code>/</code>。</p><h2 id="排障" tabindex="-1">排障 <a class="header-anchor" href="#排障" aria-label="Permalink to &quot;排障&quot;">​</a></h2><h3 id="子应用挂载后白屏-怎么定位" tabindex="-1">子应用挂载后白屏，怎么定位？ <a class="header-anchor" href="#子应用挂载后白屏-怎么定位" aria-label="Permalink to &quot;子应用挂载后白屏，怎么定位？&quot;">​</a></h3><p>按顺序检查：</p><ol><li>网络面板：入口 HTML、JS、CSS 是否 200。</li><li>控制台：是否有跨域、<code>document</code> 为空、路由冲突报错。</li><li>容器：挂载节点是否在主应用渲染前就存在。</li><li>生命周期：<code>mount</code> 是否真的被调用，返回值是否是 Promise。</li></ol><p>更多条目见<a href="/micro-frontend-docs/mastery/troubleshooting">故障手册</a>。</p><h3 id="子应用卸载后事件监听还在-导致内存泄漏" tabindex="-1">子应用卸载后事件监听还在，导致内存泄漏？ <a class="header-anchor" href="#子应用卸载后事件监听还在-导致内存泄漏" aria-label="Permalink to &quot;子应用卸载后事件监听还在，导致内存泄漏？&quot;">​</a></h3><p>在 <code>unmount</code> 中清理：移除 <code>window</code> / <code>document</code> 监听、清空定时器、取消未完成请求、销毁框架实例。微前端环境下&quot;卸载&quot;是高频操作，必须当成正式生命周期对待。</p>',63)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
